    type field_storage_t is record
        control : \usb_device.control_storage_t\;
        device_address : \usb_device.device_address_storage_t\;
        bus_event_enable : \usb_device.bus_event_enable_storage_t\;
        bus_event : \usb_device.bus_event_storage_t\;
