    ----------------------------------------------------------------------------
    -- Readback Signals
    ----------------------------------------------------------------------------
    signal rd_mux_addr : unsigned(12 downto 0);
    signal pending_rd_addr : std_logic_vector(12 downto 0);
    signal readback_external_rd_ack_c : std_logic;
    signal readback_external_rd_ack : std_logic;
    signal readback_err : std_logic;
    signal readback_done : std_logic;
    signal readback_data : std_logic_vector(31 downto 0);
begin

    ----------------------------------------------------------------------------
    -- CPU Bus interface
    ----------------------------------------------------------------------------
    

    -- Max Outstanding Transactions: 2
    -- Transaction request acceptance
    process(clk, arst_n) begin
        if not arst_n then -- async reset
            axil_prev_was_rd <= '0';
            axil_arvalid <= '0';
            axil_araddr <= (others => '0');
            axil_awvalid <= '0';
            axil_awaddr <= (others => '0');
            axil_wvalid <= '0';
            axil_wdata <= (others => '0');
            axil_wstrb <= (others => '0');
            axil_n_in_flight <= (others => '0');
        elsif rising_edge(clk) then
            if false then -- sync reset
                axil_prev_was_rd <= '0';
                axil_arvalid <= '0';
                axil_araddr <= (others => '0');
                axil_awvalid <= '0';
                axil_awaddr <= (others => '0');
                axil_wvalid <= '0';
                axil_wdata <= (others => '0');
                axil_wstrb <= (others => '0');
                axil_n_in_flight <= (others => '0');
            else
                -- AR* acceptance register
                if axil_ar_accept then
                    axil_prev_was_rd <= '1';
                    axil_arvalid <= '0';
                end if;
                if s_axil_arvalid and s_axil_arready then
                    axil_arvalid <= '1';
                    axil_araddr <= s_axil_araddr;
                end if;

                -- AW* & W* acceptance registers
                if axil_aw_accept  then
                    axil_prev_was_rd <= '0';
                    axil_awvalid <= '0';
                    axil_wvalid <= '0';
                end if;
                if s_axil_awvalid and s_axil_awready then
                    axil_awvalid <= '1';
                    axil_awaddr <= s_axil_awaddr;
                end if;
                if s_axil_wvalid and s_axil_wready then
                    axil_wvalid <= '1';
                    axil_wdata <= s_axil_wdata;
                    axil_wstrb <= s_axil_wstrb;
                end if;

                -- Keep track of in-flight transactions
                if (axil_ar_accept or axil_aw_accept) and not axil_resp_acked then
                    axil_n_in_flight <= axil_n_in_flight + 1;
                elsif not (axil_ar_accept or axil_aw_accept) and axil_resp_acked then
                    axil_n_in_flight <= axil_n_in_flight - 1;
                end if;
            end if;
        end if;
    end process;

    process(all) begin
        s_axil_arready <= not axil_arvalid or axil_ar_accept;
        s_axil_awready <= not axil_awvalid or axil_aw_accept;
        s_axil_wready <= not axil_wvalid or axil_aw_accept;
    end process;

    -- Request dispatch
    process(all) begin
        cpuif_wr_data <= axil_wdata;
        for i in axil_wstrb'RANGE loop
            cpuif_wr_biten(i*8 + 7 downto i*8) <= (others => axil_wstrb(i));
        end loop;
        cpuif_req <= '0';
        cpuif_req_is_wr <= '0';
        cpuif_addr <= (others => '0');
        axil_ar_accept <= '0';
        axil_aw_accept <= '0';

        if axil_n_in_flight < to_unsigned(2, 2) then
            -- Can safely issue more transactions without overwhelming response buffer
            if axil_arvalid and not axil_prev_was_rd then
                cpuif_req <= '1';
                cpuif_req_is_wr <= '0';
                cpuif_addr <= (12 downto 2 => axil_araddr(12 downto 2), others => '0');
                if not cpuif_req_stall_rd then
                    axil_ar_accept <= '1';
                end if;
            elsif axil_awvalid and axil_wvalid then
                cpuif_req <= '1';
                cpuif_req_is_wr <= '1';
                cpuif_addr <= (12 downto 2 => axil_awaddr(12 downto 2), others => '0');
                if not cpuif_req_stall_wr then
                    axil_aw_accept <= '1';
                end if;
            elsif axil_arvalid then
                cpuif_req <= '1';
                cpuif_req_is_wr <= '0';
                cpuif_addr <= (12 downto 2 => axil_araddr(12 downto 2), others => '0');
                if not cpuif_req_stall_rd then
                    axil_ar_accept <= '1';
                end if;
            end if;
        end if;
    end process;
    -- AXI4-Lite Response Logic
    process(clk, arst_n) begin
        if not arst_n then -- async reset
            for i in axil_resp_buffer'RANGE loop
                axil_resp_buffer(i).is_wr <= '0';
                axil_resp_buffer(i).err <= '0';
                axil_resp_buffer(i).rdata <= (others => '0');
            end loop;
            axil_resp_wptr <= (others => '0');
            axil_resp_rptr <= (others => '0');
        elsif rising_edge(clk) then
            if false then -- sync reset
                for i in axil_resp_buffer'RANGE loop
                    axil_resp_buffer(i).is_wr <= '0';
                    axil_resp_buffer(i).err <= '0';
                    axil_resp_buffer(i).rdata <= (others => '0');
                end loop;
                axil_resp_wptr <= (others => '0');
                axil_resp_rptr <= (others => '0');
            else
                -- Store responses in buffer until AXI response channel accepts them
                if cpuif_rd_ack or cpuif_wr_ack then
                    if cpuif_rd_ack then
                        axil_resp_buffer(to_integer(axil_resp_wptr(0 downto 0))).is_wr <= '0';
                        axil_resp_buffer(to_integer(axil_resp_wptr(0 downto 0))).err <= cpuif_rd_err;
                        axil_resp_buffer(to_integer(axil_resp_wptr(0 downto 0))).rdata <= cpuif_rd_data;

                    elsif cpuif_wr_ack then
                        axil_resp_buffer(to_integer(axil_resp_wptr(0 downto 0))).is_wr <= '1';
                        axil_resp_buffer(to_integer(axil_resp_wptr(0 downto 0))).err <= cpuif_wr_err;
                    end if;
                    axil_resp_wptr <= axil_resp_wptr + 1;
                end if;

                -- Advance read pointer when acknowledged
                if axil_resp_acked then
                    axil_resp_rptr <= axil_resp_rptr + 1;
                end if;
            end if;
        end if;
    end process;

    process(all) begin
        axil_resp_acked <= '0';
        s_axil_bvalid <= '0';
        s_axil_rvalid <= '0';
        if axil_resp_rptr /= axil_resp_wptr then
            if axil_resp_buffer(to_integer(axil_resp_rptr(0 downto 0))).is_wr then
                s_axil_bvalid <= '1';
                if s_axil_bready then
                    axil_resp_acked <= '1';
                end if;
            else
                s_axil_rvalid <= '1';
                if s_axil_rready then
                    axil_resp_acked <= '1';
                end if;
            end if;
        end if;

        s_axil_rdata <= axil_resp_buffer(to_integer(axil_resp_rptr(0 downto 0))).rdata;
        if axil_resp_buffer(to_integer(axil_resp_rptr(0 downto 0))).err then
            s_axil_bresp <= "10";
            s_axil_rresp <= "10";
        else
            s_axil_bresp <= "00";
            s_axil_rresp <= "00";
        end if;
    end process;


    -- Read & write latencies are balanced. Stalls not required
    -- except if external
    cpuif_req_stall_rd <= external_pending;
    cpuif_req_stall_wr <= external_pending;
    cpuif_req_masked <= cpuif_req
                        and not (not cpuif_req_is_wr and cpuif_req_stall_rd)
                        and not (cpuif_req_is_wr and cpuif_req_stall_wr);

    ----------------------------------------------------------------------------
    -- Address Decode
    ----------------------------------------------------------------------------
    process(all)
        -- overload "=" in this scope to avoid lots of type casts
        function "="(L: std_logic_vector; R: integer) return std_logic is
            variable result : std_logic;
        begin
            result := '1' when unsigned(L) = R else '0';
            return result;
        end;
        variable is_valid_addr : std_logic;
        variable is_valid_rw : std_logic;
        variable is_external : std_logic;
    begin
        is_external := '0';
        is_valid_addr := '0';
        is_valid_rw := '0';
        decoded_reg_strb.core_id <= cpuif_req_masked and (cpuif_addr = 16#0#) and not cpuif_req_is_wr;
        is_valid_addr := is_valid_addr or (cpuif_req_masked and (cpuif_addr = 16#0#));
        is_valid_rw := is_valid_rw or (cpuif_req_masked and (cpuif_addr = 16#0#) and not cpuif_req_is_wr);
        decoded_reg_strb.version <= cpuif_req_masked and (cpuif_addr = 16#4#) and not cpuif_req_is_wr;
